<?php require_once '../config.php'; login_required('admin'); $msg=''; if(isset($_POST['return_id'])){ $id=(int)$_POST['return_id'];$r=mysqli_fetch_assoc(mysqli_query($conn,"SELECT book_id,due_date FROM issues WHERE id=$id AND status!='Returned'")); if($r){$late=max(0,(int)((strtotime(date('Y-m-d'))-strtotime($r['due_date']))/86400));$fine=$late*10;mysqli_query($conn,"UPDATE issues SET return_date=CURDATE(),status='Returned',fine=$fine WHERE id=$id");mysqli_query($conn,"UPDATE books SET available=available+1 WHERE id=".$r['book_id']);$msg='Book returned. Fine: ₹'.$fine;}} $rows=mysqli_query($conn,"SELECT i.*,b.title,u.name FROM issues i JOIN books b ON i.book_id=b.id JOIN users u ON i.user_id=u.id ORDER BY i.id DESC");?><!doctype html><html><head><title>Return Book</title><link rel="stylesheet" href="../assets/css/admin/return_book.css"><link rel="stylesheet" href="../assets/css/admin/sidebar.css"></head><body><div class="layout"><?php include 'sidebar.php';?><main class="main"><h1>Return Book</h1><?php if($msg):?><div class="success"><?=$msg?></div><?php endif;?><div class="panel"><table><tr><th>Book</th><th>User</th><th>Due</th><th>Status</th><th>Fine</th><th>Action</th></tr><?php while($r=mysqli_fetch_assoc($rows)):?><tr><td><?=e($r['title'])?></td><td><?=e($r['name'])?></td><td><?=$r['due_date']?></td><td><?=$r['status']?></td><td>₹<?=$r['fine']?></td><td><?php if($r['status']!='Returned'):?><form method="post"><input type="hidden" name="return_id" value="<?=$r['id']?>"><button class="btn small green">Return</button></form><?php else:?>Done<?php endif;?></td></tr><?php endwhile;?></table></div></main></div></body></html>
